import attr
import marshmallow
from marshmallow import Schema, fields, validate
import pytest


@attr.s
class Member:
    name = attr.ib()
    other = attr.ib()


class MemberSchema(Schema):
    name = fields.String()
    other = fields.String()


@attr.s
class Holder:
    members = attr.ib()


class HolderSchema(Schema):
    members = fields.List(fields.Pluck(MemberSchema, field_name="name"))


def test_list_pluck():
    my_holder = Holder(
        members=[
            Member(name="name_0", other="other_0"),
            Member(name="name_1", other="other_1"),
        ],
    )

    dumped = HolderSchema().dump(my_holder)
    assert dumped == {"members": ["name_0", "name_1"]}
